function ExhibitorModal({item,onClose}:{item:Exhibitor;onClose:()=>void}){useEffect(()=>{const f=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();};document.addEventListener('keydown',f);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',f);document.body.style.overflow=old;};},[onClose]);return <div className="modal-backdrop" onClick={onClose}><div role="dialog" aria-modal="true" aria-label={item.company} className="exhibitor-modal" onClick={e=>e.stopPropagation()}><button className="modal-close icon-btn" onClick={onClose} aria-label="Хаах"><X/></button><div className="exhibitor-logo"><img src={item.logo} alt={item.company}/></div><span className="eyebrow"><span/>CONFIRMED EXHIBITOR</span><h2>{item.company}</h2><div className="tags"><span>{item.chapter}</span><span>{item.sector}</span><span>{item.audience}</span></div><p>{item.description}</p><div className="modal-booths"><MapPin size={18}/><b>Талбай {item.booths.join(', ')}</b><span>{areaFor(item.booths)} м²</span></div>{item.website&&<a className="btn dark" href={item.website} target="_blank" rel="noreferrer">Веб / Сошиал хуудас <ExternalLink size={16}/></a>}</div></div>;}
function ExhibitorsPage({data,error,refresh}:{data:ExpoData;error:string;refresh:()=>void}){const[view,setView]=useState<'map'|'list'>('map'),[selected,setSelected]=useState<string[]>([]),[search,setSearch]=useState(''),[chapter,setChapter]=useState(''),[sector,setSector]=useState(''),[modal,setModal]=useState<Exhibitor|null>(null),[bookingChapter,setBookingChapter]=useState('');useEffect(()=>{setBookingChapter(restoreChapter());},[]);const changeBookingChapter=(value:string)=>{setBookingChapter(value);rememberChapter(value);if(!validChapter(value))setSelected([]);};const chapters=[...new Set(data.exhibitors.map(e=>e.chapter))],sectors=[...new Set(data.exhibitors.map(e=>e.sector))];const filtered=data.exhibitors.filter(e=>(!search||`${e.company} ${e.description}`.toLowerCase().includes(search.toLowerCase()))&&(!chapter||e.chapter===chapter)&&(!sector||e.sector===sector));const toggle=(id:string)=>{if(!validChapter(bookingChapter))return;setSelected(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id]);};return <><PageHeading label="DISCOVER THE NETWORK" title={<>Бизнесүүдтэй <em>холбогд.</em></>} desc="Оролцогч байгууллагуудтай танилцаж, бизнесийнхээ дараагийн байршлыг сонгоорой."/><section className="section exhibitors-section" id="map"><div className="exhibitors-tools"><div className="segmented"><button className={view==='map'?'active':''} onClick={()=>setView('map')}><Map size={17}/>Талбайн map</button><button className={view==='list'?'active':''} onClick={()=>setView('list')}><Grid2X2 size={17}/>Оролцогчид <span>{data.exhibitors.length}</span></button></div><button className="text-link" onClick={refresh}><RefreshCw size={15}/>Шинэчлэх</button></div>{error&&<div className="notice error"><AlertCircle size={16}/>{error}</div>}{view==='map'?<><ChapterSelection chapter={bookingChapter} onChange={changeBookingChapter} chapters={data.settings.chapters}/><div className="map-layout">{validChapter(bookingChapter)?<FloorMap data={data} selected={selected} onSelect={toggle} onExhibitor={setModal} chapter={bookingChapter}/>:<ChapterMapGate/>}<aside className="selection-panel"><div className="eyebrow"><span/>YOUR NEXT SPACE</div><h3>Талбайгаа<br/>сонгоорой.</h3><p>Сул талбай дээр дарж сонгоно. Нэг байгууллага олон талбай авах боломжтой.</p><div className="availability"><span className="live-dot"/>{BOOTHS.length-data.occupancy.length} сул талбай</div>{selected.length>0?<><div className="selected-tags">{selected.map(id=><button key={id} onClick={()=>toggle(id)}>{id}<X size={13}/></button>)}</div><div className="selection-total"><span>Нийт хэмжээ <b>{areaFor(selected)} м²</b></span><span>Нийт дүн <b>{money(priceFor(selected,bookingChapter))}</b></span></div><a href={'/register?booths='+selected.join(',')+'&chapter='+encodeURIComponent(canonicalChapter(bookingChapter))} className="btn red">Хүсэлт үргэлжлүүлэх <ArrowRight size={17}/></a></>:<div className="empty-selection"><MapPin size={26}/><span>{validChapter(bookingChapter)?'Одоогоор талбай сонгоогүй':'Эхлээд chapter-аа сонгоно уу'}</span></div>}<div className="selection-note"><ShieldCheck size={17}/><p>Хүсэлт илгээсний дараа талбай 48 цаг түр нөөцлөгдөнө. Админ баталснаар оролцоо баталгаажна.</p></div><a className="small text-link" href="/assets/venue-map.webp" target="_blank" rel="noreferrer">Map зургийг бүтнээр харах <Maximize2 size={14}/></a></aside></div></>:<><div className="exhibitor-filters"><label className="search-field"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Байгууллага хайх…" aria-label="Байгууллага хайх"/></label><select value={chapter} onChange={e=>setChapter(e.target.value)} aria-label="Chapter шүүлтүүр"><option value="">Бүх chapter</option>{chapters.map(c=><option key={c}>{c}</option>)}</select><select value={sector} onChange={e=>setSector(e.target.value)} aria-label="Чиглэлийн шүүлтүүр"><option value="">Бүх чиглэл</option>{sectors.map(c=><option key={c}>{c}</option>)}</select></div>{filtered.length?<div className="exhibitor-grid">{filtered.map(item=><button key={item.id} className="exhibitor-card" onClick={()=>setModal(item)}><div><img src={item.logo} alt={item.company}/><ArrowUpRight size={20}/></div><small>{item.chapter}</small><h3>{item.company}</h3><p>{item.sector}</p><span>Талбай {item.booths.join(', ')}</span></button>)}</div>:<div className="empty-state"><Network size={45}/><h3>{search||chapter||sector?'Тохирох байгууллага олдсонгүй':'Сүлжээ эндээс бүрдэнэ.'}</h3><p>{search||chapter||sector?'Хайлтын нөхцөлөө өөрчлөөд үзээрэй.':'Баталгаажсан байгууллагуудын лого, танилцуулга энд нийтлэгдэнэ.'}</p><a className="btn dark" href="/register">Оролцох хүсэлт илгээх <ArrowUpRight size={17}/></a></div>}</>}</section>{modal&&<ExhibitorModal item={modal} onClose={()=>setModal(null)}/>}</>;}
type Meeting={company:string;person:string;goal:string};
const initialForm={company:'',chapter:'',sector:'',description:'',audience:'B2B + B2C',contact:'',position:'',phone:'',email:'',website:'',notes:'',honeypot:''};
function Registration({data,refresh}:{data:ExpoData;refresh:()=>void}){const[step,setStep]=useState(0),[selected,setSelected]=useState<string[]>([]),[form,setForm]=useState(initialForm),[meetings,setMeetings]=useState<Meeting[]>([{company:'',person:'',goal:''}]),[file,setFile]=useState<File|null>(null),[preview,setPreview]=useState(''),[consent,setConsent]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState<{id:string;token:string}|null>(null),[modal,setModal]=useState<Exhibitor|null>(null);const formRef=useRef<HTMLFormElement>(null);const labels=['Chapter & талбай','Байгууллага','Холбоо барих','121 & Илгээх'];
 useEffect(()=>{const restored=restoreChapter();if(validChapter(restored)){setForm(f=>({...f,chapter:restored}));const ids=new URLSearchParams(location.search).get('booths')?.split(',').filter(x=>boothById(x))||[];setSelected([...new Set(ids)]);}},[]);
 const changeChapter=(value:string)=>{setForm(f=>({...f,chapter:value}));rememberChapter(value);setError('');if(!validChapter(value))setSelected([]);else if(!selected.length){const ids=new URLSearchParams(location.search).get('booths')?.split(',').filter(x=>boothById(x))||[];setSelected([...new Set(ids)]);}};
 useEffect(()=>{if(!file){setPreview('');return;}const url=URL.createObjectURL(file);setPreview(url);return()=>URL.revokeObjectURL(url);},[file]);
 const field=(name:keyof typeof form,label:string,required=true,type='text',placeholder='')=><label className={name==='description'?'field full':'field'}>{label}{required&&<sup>*</sup>}{name==='description'||name==='notes'?<textarea required={required} minLength={name==='description'?10:undefined} maxLength={1200} value={form[name]} onChange={e=>setForm(f=>({...f,[name]:e.target.value}))} placeholder={placeholder} rows={4}/>:<input required={required} type={type} value={form[name]} onChange={e=>setForm(f=>({...f,[name]:e.target.value}))} placeholder={placeholder} maxLength={name==='website'?300:150} list={name==='chapter'?'chapters':undefined}/>}</label>;
 const changeFile=(f:File|undefined)=>{if(!f)return;if(f.size>5_000_000||!['image/png','image/jpeg','image/webp'].includes(f.type)){setError('Лого PNG, JPG, WebP, 5 MB-ээс бага байна.');return;}setFile(f);setError('');};
 const next=(e:React.FormEvent)=>{e.preventDefault();if(step===0&&!validChapter(form.chapter)){setError('Эхлээд chapter-аа сонгоно уу.');return;}if(step===0&&!selected.length){setError('Map-аас дор хаяж нэг талбай сонгоно уу.');return;}if(step===1&&!file){setError('Байгууллагын логог хавсаргана уу.');return;}setError('');setStep(s=>s+1);document.querySelector('#registration')?.scrollIntoView({behavior:'smooth',block:'start'});};
 const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!consent){setError('Бүртгэлийн нөхцөлийг зөвшөөрнө үү.');return;}setBusy(true);setError('');try{const fd=new FormData();fd.append('data',JSON.stringify({...form,booths:selected,meetings,consent}));if(file)fd.append('logo',file);const d=await api('/api/applications',{method:'POST',body:fd});setResult(d);refresh();}catch(e){setError((e as Error).message);refresh();}finally{setBusy(false);}};
 const invalidSelected=selected.some(id=>data.occupancy.some(o=>o.boothId===id));
 if(result)return <section className="success-page section"><CheckCircle2 size={60}/><div className="eyebrow">REQUEST RECEIVED</div><h1>Хүсэлтийг<br/><em>хүлээн авлаа.</em></h1><p><b>{form.company}</b> — таны оролцох хүсэлт бүртгэгдлээ.<br/>Админ шалгаж баталсны дараа оролцоо баталгаажна.</p><div className="receipt"><span>ХҮСЭЛТИЙН ДУГААР</span><b>{result.id}</b><p>Талбай {selected.join(', ')} · {areaFor(selected)} м²</p></div><a className="btn red" href={'/status?token='+result.token}>Хүсэлтийн төлөв харах <ArrowRight size={17}/></a><p className="small muted">Төлөв шалгах холбоосоо хадгалаарай. Баталгаажуулалтын мэдээллийг бүртгэсэн мейлээр хүргэнэ.</p></section>;
 return <><PageHeading label="BECOME AN EXHIBITOR" title={<>Сүлжээнд <em>нэгд.</em></>} desc="Талбайгаа сонгож, байгууллагаа танилцуулаад оролцох хүсэлтээ илгээгээрэй."/><section className="section registration-section" id="registration"><div className="form-steps">{labels.map((l,i)=><div key={l} className={i===step?'active':i<step?'done':''}><span>{i<step?<Check size={15}/>:String(i+1).padStart(2,'0')}</span><b>{l}</b></div>)}</div><div className="registration-layout"><form ref={formRef} onSubmit={step===3?submit:next} className="registration-form">{error&&<div className="notice error"><AlertCircle size={18}/>{error}</div>}<div className="step-title"><span>АЛХАМ 0{step+1} / 04</span><h2>{labels[step]}</h2></div>{step===0&&<><ChapterSelection chapter={form.chapter} onChange={changeChapter} chapters={data.settings.chapters}/>{validChapter(form.chapter)?<><p className="muted">Сул талбай дээр дарж нэг эсвэл олон талбай сонгоно уу.</p><FloorMap data={data} selected={selected} onSelect={id=>setSelected(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id])} onExhibitor={setModal} chapter={form.chapter}/></>:<ChapterMapGate/>}{invalidSelected&&<div className="notice error">Сонгосон талбайн төлөв өөрчлөгджээ. Сул талбай дахин сонгоно уу.</div>}</>}{step===1&&<div className="form-grid">{field('company','Байгууллагын нэр')}<div className="field chapter-readonly">BNI Chapter<sup>*</sup><strong>{canonicalChapter(form.chapter)}</strong><small>{money(tariffFor(form.chapter))} / м²</small><button type="button" className="text-link" onClick={()=>setStep(0)}>Chapter өөрчлөх <ArrowLeft size={13}/></button></div>{field('sector','Үйл ажиллагааны чиглэл',true,'text','Жишээ: Технологи, боловсрол…')}<label className="field">Оролцох чиглэл<sup>*</sup><select value={form.audience} onChange={e=>setForm(f=>({...f,audience:e.target.value}))}><option>B2B + B2C</option><option>B2B</option><option>B2C</option></select></label>{field('description','Байгууллагын товч танилцуулга',true,'text','Бүтээгдэхүүн, үйлчилгээ болон хамтын ажиллагааны боломжоо танилцуулна уу.')}<div className="field full">Байгууллагын лого<sup>*</sup><label className={'upload-zone '+(preview?'has-file':'')} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();changeFile(e.dataTransfer.files[0]);}}>{preview?<img src={preview} alt="Хавсаргасан лого"/>:<Upload size={27}/>}<b>{file?file.name:'Лого оруулах эсвэл энд чирж тавих'}</b><span>PNG, JPG, WebP · 5 MB хүртэл</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>changeFile(e.target.files?.[0])}/></label><small className="muted">Админ баталсны дараа map болон Exhibitors хэсэгт нийтлэгдэнэ.</small></div></div>}{step===2&&<div className="form-grid">{field('contact','Хариуцсан хүний нэр')}{field('position','Албан тушаал',false)}{field('phone','Холбоо барих утас',true,'tel','+976 …')}{field('email','Баталгаажуулалт хүлээн авах мейл',true,'email','name@company.mn')}{field('website','Веб / Сошиал холбоос',false,'url','https://…')}<div className="form-help"><Mail size={22}/><p>Хүсэлтийн хариу болон бүртгэлийн баталгаажуулалтыг энэ мейл хаягаар хүргэнэ.</p></div></div>}{step===3&&<><p className="muted" id="meetings">121 уулзалтаар холбогдохыг хүсэж буй байгууллага, хүн болон зорилгоо оруулна уу. Энэ нь уулзалтын хүсэл бөгөөд товлосон цагийн баталгаа биш.</p>{meetings.map((m,i)=><div className="meeting-fields" key={i}><div className="meeting-fields-title"><b>УУЛЗАЛТЫН ХҮСЭЛ 0{i+1}</b>{meetings.length>1&&<button type="button" className="icon-btn" onClick={()=>setMeetings(s=>s.filter((_,j)=>j!==i))} aria-label="Уулзалтын хүсэл устгах"><Trash2 size={16}/></button>}</div><div className="form-grid">{(['company','person','goal'] as const).map((k,j)=><label className={'field '+(k==='goal'?'full':'')} key={k}>{['Уулзах байгууллага','Уулзах хүний нэр','Уулзалтын зорилго'][j]}<sup>*</sup><input required minLength={2} maxLength={k==='goal'?500:150} value={m[k]} onChange={e=>setMeetings(s=>s.map((r,n)=>n===i?{...r,[k]:e.target.value}:r))}/></label>)}</div></div>)}<button className="text-link" type="button" onClick={()=>setMeetings(s=>[...s,{company:'',person:'',goal:''}])} disabled={meetings.length>=20}><Plus size={17}/>Уулзалтын хүсэл нэмэх</button><div className="form-grid notes-grid">{field('notes','Нэмэлт хэрэгцээ, тайлбар',false,'text','Тоног төхөөрөмж, цахилгаан, хөнгөлөлтийн хүсэлт…')}</div><div className="review-box"><b>ИЛГЭЭХИЙН ӨМНӨ ШАЛГАХ</b><h3>{form.company}</h3><p>{canonicalChapter(form.chapter)} · {form.sector} · {form.audience}</p><p>Тариф: {money(tariffFor(form.chapter))} / м² · Нийт: {money(priceFor(selected,form.chapter))}</p><p>{form.contact} · {form.phone} · {form.email}</p><p>Талбай {selected.join(', ')} · {areaFor(selected)} м²</p></div><label className="consent"><input type="checkbox" required checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>Мэдээллээ үнэн зөв оруулсан бөгөөд байгууллагын нэр, лого, танилцуулга, chapter, талбайн дугаарыг баталгаажсаны дараа нийтлэхийг зөвшөөрч байна. Хүсэлт илгээх нь оролцоо баталгаажсан гэсэн үг биш.</span></label><input className="honeypot" name="company_website_extra" tabIndex={-1} autoComplete="off" value={form.honeypot} onChange={e=>setForm(f=>({...f,honeypot:e.target.value}))} aria-hidden="true"/></>}<div className="form-actions">{step>0?<button className="btn outline" type="button" onClick={()=>{setStep(s=>s-1);setError('');}}><ArrowLeft size={16}/>Буцах</button>:<a href="/exhibitors" className="text-link">Оролцогчид харах</a>}<button className="btn red" type="submit" disabled={busy||(step===0&&invalidSelected)}>{busy?<Loader2 className="spin" size={18}/>:step===3?'Хүсэлт илгээх':'Үргэлжлүүлэх'}{!busy&&<ArrowRight size={17}/>}</button></div></form><aside className="registration-summary"><span className="eyebrow"><span/>YOUR SELECTION</span><h3>Таны оролцоо</h3>{validChapter(form.chapter)&&<div className="summary-chapter"><b>{canonicalChapter(form.chapter)}</b><span>{money(tariffFor(form.chapter))} / м²</span></div>}<div className="summary-date"><CalendarDays size={18}/><span>2026.11.20–22<br/><b>Мишээл Экспо</b></span></div>{selected.length?<><div className="selected-tags">{selected.map(id=><span key={id}>{id} <small>{boothById(id)?.area}м²</small></span>)}</div><div className="selection-total"><span>Талбайн тоо <b>{selected.length}</b></span><span>Нийт хэмжээ <b>{areaFor(selected)} м²</b></span><span>Нийт дүн <b>{money(priceFor(selected,form.chapter))}</b></span></div></>:<p className="muted">Map-аас талбайгаа сонгоорой.</p>}<p className="small muted">Нийт дүнг таны сонгосон chapter-ийн тарифаар тооцно. Спонсорын багц тусдаа тогтмол үнэтэй.</p><div className="summary-benefit"><CheckCircle2 size={18}/><span>Байгууллагын лого map дээр<br/>Exhibitors танилцуулга<br/>121 уулзалтын хүсэл</span></div></aside></div></section>{modal&&<ExhibitorModal item={modal} onClose={()=>setModal(null)}/>}</>;
}
function StatusPage(){const[data,setData]=useState<any>(null),[error,setError]=useState('');const load=useCallback(()=>{const token=new URLSearchParams(location.search).get('token');api('/api/status?token='+encodeURIComponent(token||'')).then(setData).catch(e=>setError(e.message));},[]);useEffect(load,[load]);return <section className="section status-page"><span className="eyebrow"><span/>APPLICATION STATUS</span><h1>Таны хүсэлт</h1>{error?<div className="notice error">{error}</div>:!data?<Loader2 className="spin"/>:<div className="status-card"><span className={'status-badge '+data.status}>{STATUS[data.status]}</span><h2>{data.company}</h2><p>{data.chapter}</p><dl><div><dt>Хүсэлтийн дугаар</dt><dd>{data.id}</dd></div><div><dt>Талбайнууд</dt><dd>{data.booths.join(', ')}</dd></div><div><dt>Нийт хэмжээ</dt><dd>{areaFor(data.booths)} м²</dd></div><div><dt>Chapter-ийн тариф</dt><dd>{money(data.rate_per_sqm)} / м²</dd></div><div><dt>Нийт дүн</dt><dd>{money(data.total_price)}</dd></div></dl>{data.reason&&<div className="notice">{data.reason}</div>}{data.status==='pending'&&<p className="muted">Хүсэлтийг зохион байгуулах баг шалгаж байна. Админ баталсны дараа бүртгэл баталгаажна.</p>}<button className="btn dark" onClick={load}>Төлөв шинэчлэх <RefreshCw size={16}/></button></div>}</section>;}
function Admin(){const[data,setData]=useState<any>(null),[error,setError]=useState(''),[tab,setTab]=useState('applications'),[filter,setFilter]=useState('all'),[query,setQuery]=useState(''),[selected,setSelected]=useState<any>(null),[busy,setBusy]=useState(false),[reason,setReason]=useState(''),[intent,setIntent]=useState(''),[notice,setNotice]=useState(''),[settings,setSettings]=useState<Record<string,string>>({});const load=useCallback(async()=>{try{const d=await api('/api/admin');setData(d);setSettings(d.settings);setError('');if(selected)setSelected(d.applications.find((a:any)=>a.id===selected.id));}catch(e){if((e as {status?:number}).status===401)setData(null);setError((e as Error).message);}},[selected?.id]);useEffect(()=>{load();},[]);
 const action=async(action:string,id?:string)=>{setBusy(true);setNotice('');try{const d=await api('/api/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,id,reason,values:settings})});setNotice(action==='retry_mail'&&!d.mailConfigured?'Мейл үйлчилгээ холбогдоогүй байна. Мэдэгдэл хүлээлгийн жагсаалтад хадгалагдсан.':'Өөрчлөлт хадгалагдлаа.');setIntent('');setReason('');await load();}catch(e){setNotice((e as Error).message);}finally{setBusy(false);}};
 const exportCSV=()=>{const rows=[['Байгууллага','Chapter','Төлөв','Талбай','Тариф ₮/м²','Нийт дүн ₮','Хүний нэр','Утас','Мейл','121 Байгууллага','121 Хүн','121 Зорилго'],...data.applications.flatMap((a:any)=>a.meetings.map((m:Meeting)=>[a.company,a.chapter,STATUS[a.status],a.booths.join(', '),String(a.rate_per_sqm??tariffFor(a.chapter)),String(a.total_price??priceFor(a.booths,a.chapter)),a.contact,a.phone,a.email,m.company,m.person,m.goal]))];const csv='\ufeff'+rows.map((r:string[])=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download='get-connected-registrations.csv';a.click();URL.revokeObjectURL(u);};
 const logout=async()=>{setBusy(true);try{await api('/api/admin/session',{method:'DELETE'});window.location.assign('/admin/login');}catch(e){setNotice((e as Error).message);setBusy(false);}};
 if(!data)return error?<AdminLogin/>:<section className="section admin-page"><span className="eyebrow"><span/>ORGANIZER ACCESS</span><h1>Удирдлагын төв</h1><Loader2 className="spin"/></section>;
 const rows=data.applications.filter((a:any)=>(filter==='all'||a.status===filter)&&`${a.company} ${a.chapter} ${a.email}`.toLowerCase().includes(query.toLowerCase()));
 return <section className="section admin-page"><div className="admin-top"><div><span className="eyebrow"><span/>ORGANIZER DASHBOARD</span><h1>Удирдлагын төв</h1></div><div className="admin-header-actions"><button className="btn outline" onClick={load}><RefreshCw size={16}/>Шинэчлэх</button><button className="btn dark" disabled={busy} onClick={logout}><ArrowLeft size={16}/>Гарах</button></div></div><div className="admin-stats"><div><small>НИЙТ ХҮСЭЛТ</small><b>{data.applications.length}</b></div><div><small>ШАЛГАХ ХҮСЭЛТ</small><b>{data.applications.filter((a:any)=>a.status==='pending').length}</b></div><div><small>БАТАЛГААЖСАН</small><b>{data.applications.filter((a:any)=>a.status==='approved').length}</b></div><div><small>МЕЙЛ ХОЛБОЛТ</small><b className="mail-state">{data.mailConfigured?'Холбогдсон':'Хүлээгдэж байна'}</b></div></div><div className="admin-tabs">{[['applications','Хүсэлтүүд'],['meetings','121 хүсэлтүүд'],['mail','Мейлүүд'],['settings','Тохиргоо'],['history','Үйлдлийн түүх']].map(([key,label])=><button className={tab===key?'active':''} onClick={()=>{setTab(key);setSelected(null);}} key={key}>{label}</button>)}</div>{notice&&<div className="notice">{notice}<button onClick={()=>setNotice('')} className="icon-btn" aria-label="Мэдэгдэл хаах"><X size={15}/></button></div>}{tab==='applications'&&<><div className="admin-filters"><label className="search-field"><Search size={17}/><input aria-label="Хүсэлт хайх" placeholder="Байгууллага, chapter, мейл хайх…" value={query} onChange={e=>setQuery(e.target.value)}/></label><select value={filter} onChange={e=>setFilter(e.target.value)} aria-label="Төлөв"><option value="all">Бүх төлөв</option>{Object.entries(STATUS).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><button className="btn outline" onClick={exportCSV}><Download size={16}/>CSV татах</button></div><div className="admin-split"><div className="applications-list">{rows.length?rows.map((a:any)=><button key={a.id} className={'application-item '+(selected?.id===a.id?'active':'')} onClick={()=>{setSelected(a);setIntent('');setReason('');}}><img src={'/api/logos/'+a.logo} alt=""/><div><b>{a.company}</b><small>{a.chapter} · {a.booths.join(', ')}</small><span className={'status-badge '+a.status}>{STATUS[a.status]}</span></div><ArrowUpRight size={18}/></button>):<div className="empty-state"><Building2 size={35}/><h3>Хүсэлт алга</h3><p>Шинэ хүсэлтүүд энд харагдана.</p></div>}</div>{selected?<div className="application-detail"><span className="small muted">{selected.id}</span><h2>{selected.company}</h2><div className="tags"><span>{selected.chapter}</span><span>{selected.sector}</span><span>{selected.audience}</span></div><p>{selected.description}</p><dl><div><dt>Хариуцсан хүн</dt><dd>{selected.contact} / {selected.position}</dd></div><div><dt>Утас</dt><dd>{selected.phone}</dd></div><div><dt>Мейл</dt><dd>{selected.email}</dd></div><div><dt>Талбай</dt><dd>{selected.booths.join(', ')} · {areaFor(selected.booths)} м²</dd></div><div><dt>Chapter-ийн тариф</dt><dd>{money(selected.rate_per_sqm??tariffFor(selected.chapter))} / м²</dd></div><div><dt>Нийт дүн</dt><dd>{money(selected.total_price??priceFor(selected.booths,selected.chapter))}</dd></div><div><dt>Бүртгүүлсэн</dt><dd>{new Date(selected.created_at).toLocaleString('mn-MN',{timeZone:'Asia/Ulaanbaatar'})}</dd></div></dl>{selected.notes&&<div className="notice">{selected.notes}</div>}<h4>121 УУЛЗАЛТЫН ХҮСЛҮҮД</h4>{selected.meetings.map((m:Meeting,i:number)=><p className="meeting-review" key={i}><b>{m.company} · {m.person}</b><br/>{m.goal}</p>)}{intent?<div className="decision-box"><h4>{intent==='approve'?'Хүсэлтийг батлах уу?':intent==='reject'?'Хүсэлтэд татгалзах':'Бүртгэлийг цуцлах'}</h4><p className="small">{intent==='approve'?'Байгууллагын лого map болон Exhibitors хэсэгт нийтлэгдэнэ.':'Талбайнууд суллагдаж, нийтлэгдсэн мэдээлэл map болон жагсаалтаас хасагдана.'}</p>{intent!=='approve'&&<textarea placeholder="Шалтгаан заавал оруулна уу" value={reason} onChange={e=>setReason(e.target.value)}/>}<div className="decision-actions"><button className="btn outline" disabled={busy} onClick={()=>setIntent('')}>Буцах</button><button className="btn red" disabled={busy||(intent!=='approve'&&!reason.trim())} onClick={()=>action(intent,selected.id)}>{busy?'Хадгалж байна…':'Баталгаажуулах'}</button></div></div>:<div className="decision-actions">{selected.status==='pending'&&<><button className="btn red" onClick={()=>setIntent('approve')}><Check size={16}/>Батлах</button><button className="btn outline" onClick={()=>setIntent('reject')}>Татгалзах</button><button className="text-link" onClick={()=>action('extend',selected.id)}>48 цаг сунгах</button></>}{['pending','approved'].includes(selected.status)&&<button className="text-link danger" onClick={()=>setIntent('cancel')}>Бүртгэл цуцлах</button>}</div>}</div>:<div className="application-detail empty-state"><ArrowUpRight size={40}/><p>Хүсэлт сонгож дэлгэрэнгүйг харна уу.</p></div>}</div></>}{tab==='meetings'&&<><div className="admin-top"><p>Оролцогчдын уулзахыг хүссэн байгууллага, хүмүүс. Эдгээр нь товлосон уулзалт биш.</p><button className="btn outline" onClick={exportCSV}><Download size={16}/>CSV татах</button></div><div className="table-scroll"><table><thead><tr><th>Хүсэлт гаргасан</th><th>Уулзах байгууллага</th><th>Уулзах хүн</th><th>Зорилго</th><th>Төлөв</th></tr></thead><tbody>{data.applications.flatMap((a:any)=>a.meetings.map((m:Meeting,i:number)=><tr key={a.id+i}><td><b>{a.company}</b><small>{a.chapter}</small></td><td>{m.company}</td><td>{m.person}</td><td>{m.goal}</td><td>{STATUS[a.status]}</td></tr>))}</tbody></table></div></>}{tab==='mail'&&<>{!data.mailConfigured&&<div className="notice"><Mail size={20}/><div><b>Баталгаажуулах мейл үйлчилгээ холбогдоогүй.</b><p>Илгээгчийн баталгаажсан хаяг болон мейл үйлчилгээний холболтыг тохируулсны дараа хадгалагдсан мэдэгдлүүдийг дахин илгээнэ. Одоогоор илгээгдсэн гэж тооцохгүй.</p></div></div>}<div className="table-scroll"><table><thead><tr><th>Хүлээн авагч</th><th>Хүсэлт</th><th>Төрөл</th><th>Төлөв</th><th/></tr></thead><tbody>{data.mails.map((m:any)=><tr key={m.id}><td>{m.recipient}</td><td>{m.application_id}</td><td>{{received:'Хүлээн авсан',approved:'Баталгаажсан',rejected:'Татгалзсан',cancelled:'Цуцалсан'}[m.kind as string]||m.kind}</td><td>{m.status==='sent'?'Илгээгдсэн':m.status==='failed'?'Алдаатай':'Хүлээгдэж байна'}<small>{m.error}</small></td><td>{m.status!=='sent'&&<button className="text-link" disabled={busy} onClick={()=>action('retry_mail',m.id)}>Дахин илгээх</button>}</td></tr>)}</tbody></table></div></>}{tab==='settings'&&<div className="settings-form"><h2>Сайтын мэдээлэл</h2><label className="field">Chapter-ийн жагсаалт<textarea rows={12} value={settings.chapters||''} onChange={e=>setSettings(s=>({...s,chapters:e.target.value}))} placeholder="Chapter бүрийг шинэ мөрөнд бичнэ үү"/><small>350,000 ₮/м² тарифтай бусад chapter-ийн нэрсийг энд нэмнэ. Nexus болон баталсан 14 орон нутгийн chapter-ийн 200,000 ₮/м² тариф автоматаар мөрдөгдөнө.</small></label><label className="field">Холбоо барих утас<input value={settings.contact_phone||''} onChange={e=>setSettings(s=>({...s,contact_phone:e.target.value}))}/></label><label className="field">Холбоо барих мейл<input type="email" value={settings.contact_email||''} onChange={e=>setSettings(s=>({...s,contact_email:e.target.value}))}/></label><button className="btn red" disabled={busy} onClick={()=>action('settings')}>Тохиргоо хадгалах <Check size={17}/></button></div>}{tab==='history'&&<div className="table-scroll"><table><thead><tr><th>Огноо</th><th>Хүсэлт</th><th>Үйлдэл</th><th>Тайлбар</th></tr></thead><tbody>{data.history.map((a:any)=><tr key={a.id}><td>{new Date(a.at).toLocaleString('mn-MN',{timeZone:'Asia/Ulaanbaatar'})}</td><td>{a.application_id}</td><td>{STATUS[a.action]||({submitted:'Хүсэлт илгээсэн',extended:'Хугацаа сунгасан'} as Record<string,string>)[a.action]||a.action}</td><td>{a.detail}</td></tr>)}</tbody></table></div>}</section>;
}
function FAQ(){const[active,setActive]=useState<number|null>(null);const items=[['Нэг байгууллага олон талбай авч болох уу?','Болно. Map-аас нэг болон хэд хэдэн сул талбай сонгож, нэг хүсэлтээр илгээнэ. Баталгаажвал байгууллагын лого сонгосон талбай бүр дээр байрлана.'],['Хүсэлт илгээснээр оролцоо баталгаажих уу?','Хүсэлт илгээсний дараа талбай 48 цаг түр нөөцлөгдөнө. Зохион байгуулах баг шалгаж, админ баталсны дараа оролцоо баталгаажна.'],['Chapter бөглөх шаардлагатай юу?','Тийм. Байгууллагын BNI Chapter-ийн нэрийг заавал бөглөнө.'],['121 уулзалтад хэрхэн хүсэлт гаргах вэ?','Бүртгэлийн формд уулзахыг хүссэн байгууллага, хүний нэр, уулзалтын зорилгоо заавал бичнэ. Хэд хэдэн уулзалтын хүсэл нэмэх боломжтой. Уулзалтууд 2-р давхрын терраст зохион байгуулагдана.'],['Chapter-аас хамаарч үнэ өөр үү?','Тийм. BNI Nexus болон сонголтын жагсаалтад заасан 14 орон нутгийн chapter-ийн тариф 200,000 ₮/м². Бусад chapter-ийн тариф 350,000 ₮/м². Map сонгохоос өмнө chapter-аа заавал сонгох бөгөөд нийт дүн автоматаар тооцогдоно.']];return <section className="section faq"><div><span className="eyebrow"><span/>GOOD TO KNOW</span><h2>Түгээмэл<br/><em>асуултууд.</em></h2></div><div>{items.map(([q,a],i)=><div className={'faq-item '+(active===i?'open':'')} key={q}><button onClick={()=>setActive(active===i?null:i)} aria-expanded={active===i}>{q}{active===i?<Minus size={19}/>:<Plus size={19}/>}</button>{active===i&&<p>{a}</p>}</div>)}</div></section>;}
export default function ExpoApp({page}:{page:Page}){const[data,setData]=useState<ExpoData>(INITIAL),[error,setError]=useState('');const refresh=useCallback(()=>{api('/api/expo').then(d=>{setData(d);setError('');}).catch(e=>setError(e.message));},[]);useEffect(()=>{refresh();const t=setInterval(refresh,30_000);return()=>clearInterval(t);},[refresh]);useEffect(()=>{const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));return()=>observer.disconnect();},[page]);return <><a className="skip-link" href="#main">Үндсэн агуулга руу</a><Header page={page}/><main id="main">{page==='home'?<><Home/><FAQ/></>:page==='exhibitors'?<ExhibitorsPage data={data} error={error} refresh={refresh}/>:page==='register'?<Registration data={data} refresh={refresh}/>:page==='program'?<><PageHeading label="THE PROGRAM" title={<>Мэдлэг. Холбоо. <em>Боломж.</em></>} desc="Экспоны гурван өдрийн төлөвлөсөн хөтөлбөртэй танилцаарай."/><Program/></>:page==='admin'?<Admin/>:page==='admin-login'?<AdminLogin/>:<StatusPage/>}</main><Footer settings={data.settings}/></>;}
